import pandas as pd
import numpy as np

# Define the indicators
def williams_r(data, period):
    high = data['high'].rolling(window=period).max()
    low = data['low'].rolling(window=period).min()
    wr = -100 * ((high - data['close']) / (high - low))
    return wr

def stochastic(data, fast_k_period, slow_k_period, slow_d_period):
    low = data['low'].rolling(window=fast_k_period).min()
    high = data['high'].rolling(window=fast_k_period).max()
    k = ((data['close'] - low) / (high - low)) * 100
    d = k.rolling(window=slow_d_period).mean()
    return k, d

def cci(data, period):
    tp = (data['high'] + data['low'] + data['close']) / 3
    cci = (tp - tp.rolling(window=period).mean()) / (0.015 * tp.rolling(window=period).std())
    return cci

def ichimoku(data, conversion_line_period, base_line_period, leading_span_A_period, leading_span_B_period):
